<?php
declare(strict_types=1);
foreach(['Auth','Database','JsonResponse','UserKeywordRepository']as$file)require_once dirname(__DIR__,2).'/src/'.$file.'.php';
$identity=Auth::requireUserJson();$repository=new UserKeywordRepository((new Database())->connection());$userId=(int)$identity['user_id'];
if($_SERVER['REQUEST_METHOD']==='GET')JsonResponse::send(['keywords'=>$repository->forUser($userId)]);
if(!in_array($_SERVER['REQUEST_METHOD'],['POST','DELETE'],true))JsonResponse::send(['error'=>'Nur GET, POST und DELETE sind erlaubt.'],405);Auth::requireCsrfJson();
try{$payload=json_decode(file_get_contents('php://input')?:'',true,8,JSON_THROW_ON_ERROR);if(!is_array($payload))throw new JsonException('Ungültige Anfrage.');if(array_intersect(['user_id','userId'],array_keys($payload))!==[])JsonResponse::send(['error'=>'Eine Benutzerwahl ist nicht erlaubt.'],400);if($_SERVER['REQUEST_METHOD']==='POST'){$keyword=$repository->add($userId,(string)($payload['keyword']??''));JsonResponse::send(['keyword'=>$keyword,'keywords'=>$repository->forUser($userId)],201);}$id=filter_var($payload['keyword_id']??null,FILTER_VALIDATE_INT);if($id===false||$id<1)throw new InvalidArgumentException('Ungültige Schlagwort-ID.');if(!$repository->delete($userId,(int)$id))JsonResponse::send(['error'=>'Das Schlagwort wurde nicht gefunden.'],404);JsonResponse::send(['deleted'=>true,'keywords'=>$repository->forUser($userId)]);}catch(JsonException|InvalidArgumentException$e){JsonResponse::send(['error'=>$e->getMessage()],400);}catch(DomainException$e){JsonResponse::send(['error'=>$e->getMessage()],409);}
